    for d in common:
        av = a.loc[d]; bv = b.loc[d]
        m = av.notna() & bv.notna() & np.isfinite(av) & np.isfinite(bv)
        if m.sum() >= 6:
            r = av[m].corr(bv[m], method='spearman')
            if not np.isnan(r):
                rhos.append(r)
    return float(np.mean(rhos)) if rhos else np.nan

